def g_flow():
    top=[('① Датчик',('480 °C','')),('② Енгізу\nқұрылғысы',('аналог →','сан')),('③ Деректер\nшинасы',('сан 480','')),('④ Регистр',('480','сақталды'))]
    bot=[('⑤ АЛҚ',('500 − 480','= 20')),('⑥ БҚ',('20 > 0:','қыздыр')),('⑦ Шығару\nқұрылғысы',('қыздырғышқа','сигнал')),('Пеш',('температура','көтеріледі'))]
    o=''
    for i,(t,(v1,v2)) in enumerate(top):
        x=6+84*i;o+=B(x,30,70,42,t,'bx','t-s')+T(x+35,12,v1,'t-s ac')+T(x+35,23,v2,'t-s ac')
        if i<3:o+=A(x+70,51,x+84,51)
    o+=A(293,72,293,118)
    for j,(t,(v1,v2)) in enumerate(bot):
        x=258-84*j;o+=B(x,118,70,42,t,'soft' if j==3 else ('bxa' if j==0 else 'bx'),'t-s')+T(x+35,176,v1,'t-s ac')+T(x+35,187,v2,'t-s ac')
        if j<3:o+=A(x,139,x-14,139)
    return o
